const express = require('express');
const weaviate = require('weaviate-ts-client');
const db = require('../db');

const client = weaviate.client({
  scheme: 'http',
  host: process.env.WEAVIATE_HOST || 'localhost:8080'
});

const app = express();
app.use(express.json());

app.post('/api/legal/briefs/similarity', async (req, res) => {
  const { caseDossierId, queryConcept } = req.body;

  if (!caseDossierId || !queryConcept) {
    return res.status(400).json({ error: 'caseDossierId and queryConcept required' });
  }

  // Assert that caller is an assigned counsel on the targeted case dossier
  const assignment = await db('case_counsel_assignments')
    .where({ user_id: req.user.id, case_dossier_id: caseDossierId })
    .first();

  if (!assignment) {
    return res.status(403).json({ error: 'Access denied: Attorney is not assigned to this case dossier' });
  }

  const response = await client.graphql
    .get()
    .withClassName('LegalBrief')
    .withFields('briefTitle argumentSummary caseDossierId _additional { certainty }')
    .withNearText({ concepts: [queryConcept] })
    .withWhere({
      path: ['caseDossierId'],
      operator: 'Equal',
      valueText: caseDossierId
    })
    .withLimit(3)
    .do();

  return res.json(response.data.Get.LegalBrief);
});

module.exports = app;
